def test(run,kit):
 now=100000;inv={'balance':2000000,'units':[{'unit':'u','sku':'G1','grade':'B','cert':{},'cost':1200}]};q={'quote':'q','total':1200,'pay':{'to':'0x1','wei':'1200','data':'0x11'},'units':inv['units']};l=[{'seq':1,'ts':99900,'kind':'settle','round':4,'data':{'shop':kit.shop_url}},{'seq':2,'ts':99901,'kind':'order','round':4,'data':{}},{'seq':3,'ts':99902,'kind':'settle','round':4,'data':{'shop':'other'}}]
 f={'GET /api/inventory':{'status':200,'json':inv},'POST /api/supply':{'status':402,'json':q},'GET /api/ledger?after=-5000':{'status':200,'json':l},'GET /api/ledger?after=3':{'status':200,'json':[]},'GET /api/agents':{'status':200,'json':{'agents':[{'name':'peer','card_url':'https://peer.trycloudflare.com/.well-known/agent-card.json'}]}},'GET /.well-known/agent-card.json':{'status':200,'json':{'url':'https://peer.trycloudflare.com/a2a'}},'POST /a2a':{'status':200,'json':{'result':{'parts':[{'kind':'text','text':'계란 판매 중'}]}}}}
 r=run({'mode':'metrics_full','now':now,'customer_fixture':[{'ts':99990,'text':'계란','reply':{'data':{'checkout_jwt':'jwt'}}},{'ts':99990,'text':'연결점검'}],'fixture':f},kit);assert [r['m'],r['i'],r['c'],r['s'],r['today']]==[2,1,1,1,1],r
 r=run({'mode':'inventory_units','sku':'G1','fixture':f},kit);assert r['units']==inv['units'],r
 r=run({'path':'/api/supply','body':{'sku':'G1','qty':1},'fixture':f},kit);assert r['ok'] and r['http_status']==402 and r['quote']=='q' and r['total']==1200 and set(r['pay'])=={'to','wei','data'} and r['units'][0]['unit']=='u',r
 f['POST /api/supply']={'status':200,'json':{'total':1200,'units':inv['units']}}
 r=run({'path':'/api/supply','body':{'quote':'q','tx_hash':'0x2'},'fixture':f},kit);assert r['ok'] and r['total']==1200 and r['units'][0]['sku']=='G1',r
 r=run({'mode':'a2a','shop':'peer','fixture':f},kit);assert r['reply']['parts'][0]['text']=='계란 판매 중',r
